import express, { Request, Response } from 'express';

const app = express();
app.use(express.json());

// Ví dụ minh họa sử dụng đúng các nhóm status codes
app.post('/api/v1/documents', (req: Request, res: Response) => {
  const { title } = req.body;

  // 4xx Client Error: Client gửi thiếu trường bắt buộc
  if (!title) {
    return res.status(422).json({ error: 'Title is required' });
  }

  try {
    const docId = 'doc_' + crypto.randomUUID();
    // 2xx Success: 201 Created kèm Location header
    return res
      .status(201)
      .header('Location', `/api/v1/documents/${docId}`)
      .json({ id: docId, title });
  } catch (err) {
    // 5xx Server Error: Lỗi cơ sở dữ liệu nội bộ
    return res.status(500).json({ error: 'Internal database error' });
  }
});

