import express, { Request, Response } from 'express';

const app = express();
app.use(express.json());

interface UserProfile {
  id: string;
  name: string;
  email: string;
  bio?: string;
}

const users = new Map<string, UserProfile>([
  ['1', { id: '1', name: 'Nam Nguyen', email: 'nam@example.com', bio: 'Senior Dev' }]
]);

// PUT: Ghi đè toàn bộ resource (Idempotent)
app.put('/api/v1/users/:id', (req: Request, res: Response) => {
  const { id } = req.params;
  const { name, email, bio } = req.body;
  // Bắt buộc thay thế toàn bộ, thiếu trường bio thì bio sẽ thành undefined/null
  const fullUser: UserProfile = { id, name, email, bio };
  users.set(id, fullUser);
  return res.json(fullUser);
});

// PATCH: Cập nhật từng phần (Chỉ merge các trường được gửi lên)
app.patch('/api/v1/users/:id', (req: Request, res: Response) => {
  const { id } = req.params;
  const existing = users.get(id);
  if (!existing) return res.status(404).json({ error: 'User not found' });

  // Merge cục bộ
  const updated = { ...existing, ...req.body };
  users.set(id, updated);
  return res.json(updated);
});

