import express, { Request, Response, NextFunction } from 'express';

const app = express();

// 1. Logging Middleware: Chạy đầu tiên (Lớp ngoài cùng của củ hành)
app.use((req: Request, res: Response, next: NextFunction) => {
  const start = Date.now();
  res.on('finish', () => {
    console.log(`[${req.method}] ${req.url} - ${res.statusCode} (${Date.now() - start}ms)`);
  });
  next(); // Chuyển sang middleware tiếp theo
});

// 2. Parser Middleware: Bắt buộc phải đặt trước các middleware đọc body
app.use(express.json());

// 3. Auth Middleware: Đặt trước Route Handlers cần bảo vệ
app.use('/api/v1/protected', (req: Request, res: Response, next: NextFunction) => {
  const token = req.headers.authorization;
  if (!token) return res.status(401).json({ error: 'Unauthorized' });
  next();
});

// 4. Route Handler
app.get('/api/v1/protected/data', (req, res) => {
  res.json({ secret: 'Super confidential data' });
});

// 5. Global Error Handler: BẮT BUỘC ĐẶT Ở CUỐI CÙNG (4 tham số: err, req, res, next)
app.use((err: any, req: Request, res: Response, next: NextFunction) => {
  console.error('[GLOBAL ERROR]', err);
  res.status(500).json({ error: 'Internal Server Error' });
});

