// Thiết kế Resource-centric RESTful API chuẩn mực:
// GET    /api/v1/orders          -> Lấy danh sách đơn hàng
// POST   /api/v1/orders          -> Tạo mới đơn hàng
// GET    /api/v1/orders/:id      -> Chi tiết đơn hàng
// PUT    /api/v1/orders/:id      -> Thay thế toàn bộ đơn hàng
// PATCH  /api/v1/orders/:id      -> Cập nhật một phần đơn hàng
// DELETE /api/v1/orders/:id      -> Xóa đơn hàng
// POST   /api/v1/orders/:id/pay  -> Hành động nghiệp vụ đặc thù (RPC-style sub-resource)

import express, { Request, Response } from 'express';

const app = express();
app.use(express.json());

// Ví dụ Level 3 HATEOAS: Phản hồi kèm theo các hypermedia links chỉ dẫn hành động tiếp theo
app.get('/api/v1/orders/:id', (req: Request, res: Response) => {
  const orderId = req.params.id;

  return res.json({
    id: orderId,
    amount: 500000,
    status: 'PENDING',
    _links: {
      self: { href: `/api/v1/orders/${orderId}` },
      payment: { href: `/api/v1/orders/${orderId}/payments`, method: 'POST' },
      cancel: { href: `/api/v1/orders/${orderId}`, method: 'DELETE' }
    }
  });
});

