// Ma trận phân loại HTTP Methods:
export const HttpMethodCharacteristics = {
  GET:     { safe: true,  idempotent: true  },
  HEAD:    { safe: true,  idempotent: true  },
  OPTIONS: { safe: true,  idempotent: true  },
  PUT:     { safe: false, idempotent: true  }, // Thay thế toàn bộ: N lần cùng payload -> cùng state
  DELETE:  { safe: false, idempotent: true  }, // Xóa tài nguyên: N lần gọi -> tài nguyên vẫn bị xóa
  POST:    { safe: false, idempotent: false }, // Tạo mới / Append: N lần gọi -> N bản ghi mới
  PATCH:   { safe: false, idempotent: false }  // Cập nhật từng phần: Có thể tăng/giảm giá trị
};

// Minh họa xử lý Idempotent cho POST bằng Header Idempotency-Key
import Redis from 'ioredis';
const redis = new Redis();

export async function processPaymentWithIdempotency(key: string, amount: number, chargeFn: () => Promise<any>) {
  // Atomic SET NX: Chỉ thực thi nếu key chưa từng tồn tại
  const acquired = await redis.set(`idemp:${key}`, 'PROCESSING', 'EX', 120, 'NX');
  if (!acquired) {
    throw new Error('Duplicate transaction request in progress or already processed.');
  }

  try {
    const result = await chargeFn();
    await redis.set(`idemp:${key}`, JSON.stringify(result), 'EX', 86400);
    return result;
  } catch (err) {
    await redis.del(`idemp:${key}`); // Xóa lock nếu lỗi để client retry
    throw err;
  }
}

