import express, { Request, Response } from 'express';
import { Pool } from 'pg';

const pool = new Pool();
const app = express();

app.get('/api/v1/transactions', async (req: Request, res: Response) => {
  const limit = Math.min(Number(req.query.limit) || 20, 100);
  const cursor = req.query.cursor as string | undefined;

  let query: string;
  let params: any[];

  if (cursor) {
    // Giải mã Base64 cursor: "2026-03-01T10:00:00.000Z_tx123"
    const [createdAt, id] = Buffer.from(cursor, 'base64').toString('utf8').split('_');
    // Truy vấn Keyset chuẩn xác O(log N)
    query = `
      SELECT id, amount, status, created_at
      FROM transactions
      WHERE (created_at, id) < ($1, $2)
      ORDER BY created_at DESC, id DESC
      LIMIT $3;
    `;
    params = [new Date(createdAt), id, limit + 1];
  } else {
    query = `
      SELECT id, amount, status, created_at
      FROM transactions
      ORDER BY created_at DESC, id DESC
      LIMIT $1;
    `;
    params = [limit + 1];
  }

  const { rows } = await pool.query(query, params);
  const hasMore = rows.length > limit;
  const items = hasMore ? rows.slice(0, limit) : rows;

  let nextCursor: string | null = null;
  if (hasMore) {
    const lastItem = items[items.length - 1];
    nextCursor = Buffer.from(`${lastItem.created_at.toISOString()}_${lastItem.id}`).toString('base64');
  }

  return res.json({
    data: items,
    pageInfo: { hasMore, nextCursor }
  });
});

