import express, { Request, Response } from 'express';
import Redis from 'ioredis';
import { Pool } from 'pg';

const redis = new Redis();
const pool = new Pool();
const app = express();
app.use(express.json());

app.post('/api/v1/orders', async (req: Request, res: Response) => {
  const { orderToken, items, userId } = req.body;
  if (!orderToken) return res.status(400).json({ error: 'orderToken is required' });

  const lockKey = `lock:order:${userId}:${orderToken}`;

  // 1. LỚP 1: Distributed Lock qua Redis
  const locked = await redis.set(lockKey, 'IN_PROGRESS', 'EX', 30, 'NX');
  if (!locked) {
    return res.status(409).json({ error: 'Order is currently being processed. Please do not re-submit.' });
  }

  const client = await pool.connect();
  try {
    await client.query('BEGIN');

    // 2. LỚP 2: Database Unique Constraint trên client_idempotency_token
    const insertQuery = `
      INSERT INTO orders (id, user_id, idempotency_token, status, created_at)
      VALUES ($1, $2, $3, 'CREATED', NOW())
      RETURNING id, status;
    `;
    const { rows } = await client.query(insertQuery, [crypto.randomUUID(), userId, orderToken]);

    await client.query('COMMIT');
    return res.status(201).json(rows[0]);
  } catch (err: any) {
    await client.query('ROLLBACK');
    if (err.code === '23505') { // Postgres Unique Violation
      return res.status(409).json({ error: 'Order has already been created.' });
    }
    return res.status(500).json({ error: 'Failed to create order.' });
  } finally {
    client.release();
    await redis.del(lockKey); // Giải phóng lock
  }
});

