import express, { Request, Response, NextFunction } from 'express';
import Redis from 'ioredis';

const redis = new Redis();
const app = express();

// Sliding Window Counter Middleware chuẩn mực
export function rateLimiter(limit: number, windowSeconds: number) {
  return async (req: Request, res: Response, next: NextFunction) => {
    // Xác định Key: Ưu tiên User ID > API Key > Real IP (từ Cloudflare/X-Forwarded-For)
    const identifier = req.headers['x-api-key'] || req.ip || 'unknown';
    const key = `ratelimit:${identifier}`;
    const now = Date.now();
    const windowStart = now - windowSeconds * 1000;

    // Thực thi Redis Pipeline nguyên tử
    const pipeline = redis.pipeline();
    pipeline.zremrangebyscore(key, 0, windowStart);
    pipeline.zadd(key, now, `${now}-${Math.random()}`);
    pipeline.zcard(key);
    pipeline.expire(key, windowSeconds);

    const results = await pipeline.exec();
    const requestCount = (results?.[2]?.[1] as number) || 0;

    // Trả về headers chuẩn IETF
    res.setHeader('RateLimit-Limit', limit);
    res.setHeader('RateLimit-Remaining', Math.max(0, limit - requestCount));
    res.setHeader('RateLimit-Reset', windowSeconds);

    if (requestCount > limit) {
      res.setHeader('Retry-After', windowSeconds);
      return res.status(429).json({
        error: 'Too Many Requests',
        message: `Quota exceeded. Try again in ${windowSeconds} seconds.`
      });
    }

    next();
