      .status(422)
      .contentType('application/problem+json')
      .json({
        type: 'https://api.example.com/errors/validation-failed',
        title: 'Validation Failed',
        status: 422,
        detail: 'One or more fields failed validation.',
        instance: `/errors/${traceId}`,
        invalidParams: err.errors // [{ field: 'email', reason: 'Invalid email' }]
      });
  }

  // 2. Lỗi Server nội bộ không lường trước (500) - GIẤU KÍN STACK TRACE!
  console.error(`[CRITICAL] TraceID: ${traceId}`, err.stack);

  return res
    .status(500)
    .contentType('application/problem+json')
    .json({
      type: 'https://api.example.com/errors/internal-error',
      title: 'Internal Server Error',
      status: 500,
      detail: 'An unexpected internal error occurred. Please provide the instance ID to support.',
      instance: `/errors/${traceId}`
    });
});

