import express, { Request, Response } from 'express';
import crypto from 'crypto';

const app = express();

const articleData = {
  id: 'art_123',
  title: 'Kiến trúc Backend chuẩn Enterprise',
  content: 'Nội dung bài viết chi tiết...',
  updatedAt: '2026-03-20T10:00:00Z'
};

app.get('/api/v1/articles/:id', (req: Request, res: Response) => {
  // 1. Tính toán Strong ETag từ nội dung dữ liệu
  const contentHash = crypto
    .createHash('md5')
    .update(JSON.stringify(articleData))
    .digest('hex');
  const etag = `"${contentHash}"`;

  // 2. Kiểm tra Conditional Request từ Client
  const clientEtag = req.headers['if-none-match'];
  if (clientEtag === etag) {
    // Dữ liệu chưa từng đổi -> Trả 304 Not Modified với Body rỗng (Tiết kiệm băng thông!)
    return res.status(304).end();
  }

  // 3. Trả dữ liệu mới kèm Cache Headers
  res.setHeader('ETag', etag);
  // Cache ở browser 10 phút, bắt buộc revalidate sau đó
  res.setHeader('Cache-Control', 'public, max-age=600, must-revalidate');
  return res.status(200).json(articleData);
});

