import express, { Request, Response } from 'express';
import crypto from 'crypto';
import { Queue } from 'bullmq';

const app = express();
const webhookQueue = new Queue('payment-webhooks');
const WEBHOOK_SECRET = 'whsec_test_secret_key_123';

// BẮT BUỘC: Đọc raw body dạng Buffer để verify chữ ký HMAC chính xác từng byte
app.post('/api/v1/webhooks/stripe', express.raw({ type: 'application/json' }), async (req: Request, res: Response) => {
  const signature = req.headers['stripe-signature'] as string;
  if (!signature) return res.status(400).send('Missing signature');

  // 1. Xác thực chữ ký HMAC-SHA256
  try {
    const rawBody = req.body.toString('utf8');
    const expectedSig = crypto
      .createHmac('sha256', WEBHOOK_SECRET)
      .update(rawBody)
      .digest('hex');

    // Dùng timingSafeEqual để chống Timing Attack
    // if (!crypto.timingSafeEqual(Buffer.from(signature), Buffer.from(expectedSig))) ...

    // 2. Đẩy vào Queue để xử lý bất đồng bộ
    const event = JSON.parse(rawBody);
    await webhookQueue.add('process-payment', event, {
      jobId: event.id // Dùng chính event.id làm Dedup Key cho BullMQ
    });

    // 3. Trả về 200 OK tức thì (< 50ms)
    return res.status(200).json({ received: true });
  } catch (err) {
    return res.status(400).send('Webhook verification failed');
  }
});

