import { Pool } from 'pg';

const pool = new Pool();

// GIẢI PHÁP 1: Atomic Database Update (Tốc độ cao nhất, không cần khóa kéo dài)
export async function buyTicketAtomic(ticketId: string, userId: string) {
  const query = `
    UPDATE tickets
    SET user_id = $1, status = 'SOLD', updated_at = NOW()
    WHERE id = $2 AND status = 'AVAILABLE'
    RETURNING id;
  `;
  const result = await pool.query(query, [userId, ticketId]);
  return result.rowCount === 1; // True nếu mua thành công, False nếu đã bị người khác mua trước!
}

// GIẢI PHÁP 2: Pessimistic Locking (FOR UPDATE) cho nghiệp vụ phức tạp
export async function buyTicketPessimistic(ticketId: string, userId: string) {
  const client = await pool.connect();
  try {
    await client.query('BEGIN');

    // Khóa độc quyền dòng này, request khác tới phải đứng chờ
    const selectQuery = 'SELECT id, status FROM tickets WHERE id = $1 FOR UPDATE';
    const { rows } = await client.query(selectQuery, [ticketId]);

    if (rows.length === 0 || rows[0].status !== 'AVAILABLE') {
      await client.query('ROLLBACK');
      return false;
    }

    await client.query("UPDATE tickets SET user_id = $1, status = 'SOLD' WHERE id = $2", [userId, ticketId]);
    await client.query('COMMIT');
    return true;
  } catch (err) {
    await client.query('ROLLBACK');
    throw err;
  } finally {
    client.release();
  }
}

