    customer_name VARCHAR(100) NOT NULL,

    -- PHI CHUẨN HÓA TÍNH TOÁN: Lưu sẵn tổng số lượng mặt hàng
    total_items_count INT NOT NULL DEFAULT 0,

    total_amount NUMERIC(12, 2) NOT NULL,
    created_at TIMESTAMPTZ DEFAULT NOW()
  );
`;

