// Minh họa EXPLAIN ANALYZE đo lường sự khác biệt giữa Full Table Scan và B-Tree Index:

// 1. TRƯỚC KHI CÓ INDEX:
// EXPLAIN ANALYZE SELECT * FROM users WHERE email = 'nam@example.com';
// -> Seq Scan on users  (cost=0.00..184500.00 rows=1 width=120) (actual time=1240.502..1240.504 rows=1 loops=1)
// -> Quét toàn bộ 10.000.000 dòng từ đĩa! Thời gian: ~1.2 giây

// 2. TẠO B-TREE INDEX TRÊN CỘT EMAIL:
export const createIndexSql = `
  CREATE INDEX idx_users_email ON users(email);
`;

// 3. SAU KHI CÓ INDEX:
// EXPLAIN ANALYZE SELECT * FROM users WHERE email = 'nam@example.com';
// -> Index Scan using idx_users_email on users  (cost=0.43..8.45 rows=1 width=120) (actual time=0.025..0.027 rows=1 loops=1)
// -> Chỉ đọc 3 pages trong B-Tree! Thời gian: 0.02 mili-giây (Nhanh gấp 50.000 lần!)

