import { Pool } from 'pg';

const pool = new Pool();

// Luồng Chuyển tiền an toàn tuyệt đối bằng Transaction
export async function transferMoney(fromAccountId: string, toAccountId: string, amount: number) {
  // Lấy 1 connection duy nhất từ pool (BẮT BUỘC: transaction phải chạy trên cùng 1 kết nối!)
  const client = await pool.connect();

  try {
    // 1. Bắt đầu Transaction
    await client.query('BEGIN');

    // 2. Trừ tiền tài khoản nguồn (Kèm kiểm tra số dư đủ)
    const deductRes = await client.query(
      'UPDATE accounts SET balance = balance - $1 WHERE id = $2 AND balance >= $1 RETURNING balance',
      [amount, fromAccountId]
    );

    if (deductRes.rowCount === 0) {
      throw new Error('Số dư tài khoản không đủ để thực hiện chuyển tiền!');
    }

    // 3. Cộng tiền tài khoản đích
    const addRes = await client.query(
      'UPDATE accounts SET balance = balance + $1 WHERE id = $2',
      [amount, toAccountId]
    );

    if (addRes.rowCount === 0) {
      throw new Error('Tài khoản đích không tồn tại!');
    }

    // 4. Mọi thứ thành công mỹ mãn -> COMMIT vĩnh viễn
    await client.query('COMMIT');
    console.log('Chuyển tiền thành công!');
    return true;
  } catch (err: any) {
    // 5. Có bất kỳ lỗi nào -> ROLLBACK sạch sẽ, tài khoản A không bị mất một xu nào!
    await client.query('ROLLBACK');
    console.error('Giao dịch thất bại, đã rollback toàn bộ:', err.message);
    throw err;
  } finally {
    // 6. Luôn giải phóng kết nối trả về cho pool
    client.release();
  }
}

