import { Pool } from 'pg';

// Cấu hình Connection Pool chuẩn Enterprise trong Node.js (pg)
export const dbPool = new Pool({
  host: process.env.DB_HOST || 'localhost',
  port: 5432,
  user: process.env.DB_USER || 'postgres',
  password: process.env.DB_PASSWORD,
  database: 'production_db',

  // CẤU HÌNH POOL CHUẨN MỰC:
  max: 20,                       // Số kết nối tối đa trong pool (Tránh làm tràn DB max_connections)
  min: 4,                        // Số kết nối duy trì thường trực
  idleTimeoutMillis: 30000,      // Đóng kết nối nếu không dùng sau 30 giây
  connectionTimeoutMillis: 2000, // Quăng lỗi nếu chờ lấy kết nối quá 2 giây (Fail-fast!)
});

// Giám sát trạng thái Pool trong hệ thống APM
export function logPoolMetrics() {
  console.log({
    totalConnections: dbPool.totalCount, // Tổng số kết nối hiện có
    idleConnections: dbPool.idleCount,   // Số kết nối rảnh rỗi sẵn sàng phục vụ
    waitingClients: dbPool.waitingCount  // Số request đang phải xếp hàng chờ kết nối (Nếu > 0 là CẢNH BÁO!)
  });
}

