import Redis from 'ioredis';

const redis = new Redis();

async function demonstrateRedisDataStructures() {
  // 1. STRING: Bộ đếm Atomic & Distributed Lock
  await redis.set('cache:user:1', JSON.stringify({ name: 'Nam' }), 'EX', 3600);
  await redis.incr('page:views:today'); // Tăng bộ đếm an toàn không race condition

  // 2. HASH: Lưu trữ đối tượng có cấu trúc
  await redis.hset('user:profile:100', { name: 'Nam Nguyen', role: 'admin', points: '1500' });
  const points = await redis.hget('user:profile:100', 'points');

  // 3. LIST: Hàng đợi công việc FIFO
  await redis.lpush('task_queue', 'job_email_1', 'job_email_2');
  const nextJob = await redis.rpop('task_queue'); // Lấy ra xử lý

  // 4. SET: Tập hợp duy nhất (Tagging, Unique Voters)
  await redis.sadd('post:1:tags', 'typescript', 'backend', 'redis');
  const isTagged = await redis.sismember('post:1:tags', 'backend'); // O(1)

  // 5. SORTED SET (ZSET): Bảng xếp hạng điểm số (Score = Points)
  await redis.zadd('leaderboard', 5000, 'player_nam', 4200, 'player_an', 6100, 'player_tuan');
  // Lấy Top 3 người chơi điểm cao nhất
  const topPlayers = await redis.zrevrange('leaderboard', 0, 2, 'WITHSCORES');
  console.log('Top 3 Leaderboard:', topPlayers);
}

