-- 1. Tạo Index an toàn không khóa bảng trên PostgreSQL:
-- BẮT BUỘC có CONCURRENTLY để không chặn các lệnh INSERT/UPDATE của người dùng!
CREATE INDEX CONCURRENTLY idx_users_phone_number ON users(phone_number);

-- 2. Thêm cột mới an toàn với Default Value:
-- Trong Postgres 11+, thêm cột có default không còn ghi đè toàn bảng nữa (tốc độ O(1))
ALTER TABLE users ADD COLUMN phone_number VARCHAR(20) DEFAULT NULL;

-- 3. Script Backfill dữ liệu theo mẻ (Batching) tránh khóa bảng:
-- DO $$
-- DECLARE
--   r RECORD;
-- BEGIN
--   FOR r IN SELECT id, phone FROM users WHERE phone_number IS NULL LIMIT 1000
--   LOOP
--     UPDATE users SET phone_number = r.phone WHERE id = r.id;
--   END LOOP;
-- END $$;

