import { Pool } from 'pg';

// Mô hình Định tuyến Cơ sở dữ liệu thông minh (Smart Database Router)
const primaryDb = new Pool({ connectionString: process.env.PRIMARY_DB_URL });
const replicaDb = new Pool({ connectionString: process.env.REPLICA_DB_URL });

export async function getUserProfile(userId: string, lastWriteTimestamp?: number) {
  const now = Date.now();

  // ĐẢM BẢO READ-YOUR-OWN-WRITES:
  // Nếu user vừa thực hiện thao tác ghi trong vòng 5 giây trước, đọc thẳng từ PRIMARY!
  if (lastWriteTimestamp && (now - lastWriteTimestamp < 5000)) {
    console.log('[ROUTER] Reading from PRIMARY to prevent stale data due to replication lag.');
    const { rows } = await primaryDb.query('SELECT * FROM users WHERE id = $1', [userId]);
    return rows[0];
  }

  // Ngược lại, đọc từ REPLICA để giảm tải cho Primary DB
  console.log('[ROUTER] Reading from REPLICA.');
  const { rows } = await replicaDb.query('SELECT * FROM users WHERE id = $1', [userId]);
  return rows[0];
}

