import crypto from 'crypto';

// Shard Router mô phỏng phân tán dữ liệu theo User ID (Consistent Hashing)
class SimpleShardRouter {
  private shardNodes: string[];

  constructor(nodes: string[]) {
    this.shardNodes = nodes; // ['db_shard_01', 'db_shard_02', 'db_shard_03', 'db_shard_04']
  }

  // Xác định chính xác máy chủ Database nào sẽ lưu trữ dữ liệu của User này
  public getShardNode(userId: string): string {
    const hash = crypto.createHash('md5').update(userId).digest('hex');
    // Lấy 8 ký tự đầu chuyển thành số nguyên và chia lấy dư theo số lượng Shards
    const numericValue = parseInt(hash.substring(0, 8), 16);
    const shardIndex = numericValue % this.shardNodes.length;
    return this.shardNodes[shardIndex];
  }
}

const router = new SimpleShardRouter(['postgres_shard_1', 'postgres_shard_2', 'postgres_shard_3']);
console.log('User nam_1 trỏ tới:', router.getShardNode('user_nam_1'));
console.log('User tuan_2 trỏ tới:', router.getShardNode('user_tuan_2'));

