import { PoolClient } from 'pg';

// PHÒNG CHỐNG DEADLOCK TUYỆT ĐỐI BẰNG DETERMINISTIC LOCK ORDERING:
export async function safeTransferFunds(client: PoolClient, fromId: number, toId: number, amount: number) {
  // 1. SẮP XẾP THỨ TỰ KHÓA CỐ ĐỊNH NHẤT QUÁN THEO ID
  // Bất kể ai chuyển cho ai, tài nguyên có ID nhỏ hơn LUÔN LUÔN được khóa trước!
  const firstLockId = Math.min(fromId, toId);
  const secondLockId = Math.max(fromId, toId);

  try {
    await client.query('BEGIN');

    // Khóa tài khoản 1 trước
    await client.query('SELECT id, balance FROM accounts WHERE id = $1 FOR UPDATE', [firstLockId]);
    // Khóa tài khoản 2 sau (Không bao giờ có chu trình chờ chéo -> TRIỆT TIÊU HOÀN TOÀN DEADLOCK!)
    await client.query('SELECT id, balance FROM accounts WHERE id = $1 FOR UPDATE', [secondLockId]);

    // Thực hiện trừ và cộng tiền an toàn...
    await client.query('UPDATE accounts SET balance = balance - $1 WHERE id = $2', [amount, fromId]);
    await client.query('UPDATE accounts SET balance = balance + $1 WHERE id = $2', [amount, toId]);

    await client.query('COMMIT');
  } catch (err) {
    await client.query('ROLLBACK');
    throw err;
  }
}

