import crypto from 'crypto';

// Mô phỏng cấu trúc Bloom Filter cơ bản
class SimpleBloomFilter {
  private size: number;
  private bitArray: Uint8Array;
  private hashCount: number;

  constructor(sizeInBits: number = 1000000, hashCount: number = 3) {
    this.size = sizeInBits;
    this.bitArray = new Uint8Array(Math.ceil(sizeInBits / 8));
    this.hashCount = hashCount;
  }

  private getHashes(value: string): number[] {
    const hashes: number[] = [];
    for (let i = 0; i < this.hashCount; i++) {
      const hash = crypto.createHash('md5').update(value + i.toString()).digest('hex');
      hashes.push(parseInt(hash.substring(0, 8), 16) % this.size);
    }
    return hashes;
  }

  public add(item: string): void {
    const indices = this.getHashes(item);
    for (const index of indices) {
      const byteIndex = Math.floor(index / 8);
      const bitIndex = index % 8;
      this.bitArray[byteIndex] |= (1 << bitIndex);
    }
  }

  public contains(item: string): boolean {
    const indices = this.getHashes(item);
    for (const index of indices) {
      const byteIndex = Math.floor(index / 8);
      const bitIndex = index % 8;
      if ((this.bitArray[byteIndex] & (1 << bitIndex)) === 0) {
        return false; // KHẲNG ĐỊNH CHẮC CHẮN 100% KHÔNG TỒN TẠI!
      }
    }
    return true; // Có thể tồn tại (với một tỉ lệ false positive nhỏ chấp nhận được)
  }
}

