// Thiết lập HTTP Headers từ Server Gốc (Origin) để chỉ dẫn CDN Cache tối ưu
import express, { Request, Response } from 'express';

const app = express();

// Phục vụ Assets tĩnh: Hướng dẫn CDN cache mạnh mẽ trong 1 năm
app.use('/static', express.static('public', {
  maxAge: '365d',
  immutable: true, // Báo cho CDN biết file này không bao giờ đổi nội dung (Cache Busting bằng hash URL)
  setHeaders: (res: Response) => {
    // Chỉ thị CDN Cloudflare / CloudFront lưu cache ở Edge
    res.setHeader('Cache-Control', 'public, max-age=31536000, immutable');
  }
}));

// API động nhưng có thể cache ngắn hạn tại CDN (Micro-caching)
app.get('/api/v1/public/news', (req: Request, res: Response) => {
  // s-maxage=60: Cache ở CDN Edge trong 60 giây (Origin chỉ chịu 1 req/phút!)
  // max-age=10: Cache ở trình duyệt người dùng 10 giây
  // stale-while-revalidate=30: Trả ngay dữ liệu cũ trong lúc CDN ngầm revalidate với Origin
  res.setHeader('Cache-Control', 'public, max-age=10, s-maxage=60, stale-while-revalidate=30');

  return res.json({ news: ['Tin tuc 1', 'Tin tuc 2'], fetchedAt: new Date().toISOString() });
});

