# Cấu hình Nginx minh họa cả L7 Routing và Thuật toán Load Balancing:

# 1. Thuật toán Least Connections (Ưu tiên server ít tải nhất)
upstream backend_cluster {
    least_conn;
    server backend-node-1.internal:8000 weight=3; # Server mạnh nhận trọng số cao
    server backend-node-2.internal:8000 weight=1;
    keepalive 32;
}

# 2. Cân bằng tải L7: Định tuyến dựa trên URL Path
server {
    listen 80;
    server_name api.company.com;

    # Định tuyến sang service xác thực
    location /api/v1/auth/ {
        proxy_pass http://auth-service.internal:8001;
    }

    # Định tuyến sang cụm cluster xử lý đơn hàng
    location /api/v1/orders/ {
        proxy_pass http://backend_cluster;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
    }
}

