// ✅ STATELESS CHUẨN CLOUD-NATIVE (Scale 1.000 pods thoải mái):
import express, { Request, Response } from 'express';
import Redis from 'ioredis';

const app = express();
const redis = new Redis(process.env.REDIS_URL || 'redis://localhost:6379');

// Mọi pods đều chia sẻ chung một Distributed Session Store (Redis)
app.post('/api/v1/auth/session', async (req: Request, res: Response) => {
  const sessionId = crypto.randomUUID();
  const userData = { userId: 'usr_99', role: 'customer' };

  // Lưu trạng thái ra Redis trung tâm với TTL 24h
  await redis.set(`session:${sessionId}`, JSON.stringify(userData), 'EX', 86400);

  // Trả sessionId về cho client qua Cookie hoặc Header
  return res.json({ sessionId });
});

app.get('/api/v1/user/me', async (req: Request, res: Response) => {
  const sessionId = req.headers['x-session-id'] as string;
  // Bất kỳ Pod nào nhận request này cũng đều đọc được session từ Redis!
  const sessionStr = await redis.get(`session:${sessionId}`);
  if (!sessionStr) return res.status(401).json({ error: 'Unauthorized' });

  return res.json(JSON.parse(sessionStr));
});

