const app = express();
const pool = new Pool();

app.get('/api/v1/work', async (req, res) => {
  // Giả lập tác vụ xử lý mất 3 giây
  await new Promise(r => setTimeout(r, 3000));
  res.json({ status: 'done' });
});

const server = app.listen(8000, () => {
  console.log('Server running on port 8000');
});

// QUY TRÌNH GRACEFUL SHUTDOWN CHUẨN KUBERNETES:
function setupGracefulShutdown() {
  const handleShutdown = async (signal: string) => {
    console.log(`Received ${signal}. Starting graceful shutdown...`);

    // 1. Ngừng nhận request mới (Connection Draining)
    server.close(async () => {
      console.log('HTTP server closed. No more requests accepted.');

      try {
        // 2. Chờ và đóng an toàn Database Pool
        console.log('Closing database connection pool...');
        await pool.end();
        console.log('Database connections closed cleanly.');

        // 3. Thoát tiến trình an toàn
        process.exit(0);
      } catch (err) {
        console.error('Error during shutdown:', err);
        process.exit(1);
      }
    });

    // 4. Force Kill nếu sau 25s vẫn chưa dọn dẹp xong (chặn treo tiến trình)
    setTimeout(() => {
      console.error('Shutdown timed out after 25s. Forcing exit!');
      process.exit(1);
    }, 25000);
  };

  process.on('SIGTERM', () => handleShutdown('SIGTERM'));
  process.on('SIGINT', () => handleShutdown('SIGINT'));
}

setupGracefulShutdown();

