// Minh họa cách tạo Log có cấu trúc gắn kết chặt chẽ với Trace Context (OpenTelemetry)
import { trace } from '@opentelemetry/api';

export function structuredLogger(level: 'INFO' | 'WARN' | 'ERROR', message: string, context: Record<string, any> = {}) {
  // Lấy Span và Trace Context hiện tại từ OpenTelemetry
  const currentSpan = trace.getActiveSpan();
  const spanContext = currentSpan?.spanContext();

  const logPayload = {
    timestamp: new Date().toISOString(),
    level,
    message,
    // LIÊN KẾT SỐNG CÒN: Tự động đính kèm TraceID và SpanID vào từng dòng Log!
    traceId: spanContext?.traceId || 'no-trace',
    spanId: spanContext?.spanId || 'no-span',
    ...context
  };

  // Xuất JSON log ra stdout để FluentBit / Loki thu thập
  console.log(JSON.stringify(logPayload));
}

