  // Đẩy task vào hàng đợi kèm cấu hình Retry tự động thông minh
  await emailQueue.add('send-welcome', { email, name }, {
    attempts: 5, // Tự động retry 5 lần nếu SMTP lỗi
    backoff: {
      type: 'exponential',
