// Backend: Khởi tạo S3 Multipart Upload và cấp Presigned URLs cho Client
import { S3Client, CreateMultipartUploadCommand, UploadPartCommand, CompleteMultipartUploadCommand } from '@aws-sdk/client-s3';
import { getSignedUrl } from '@aws-sdk/s3-request-presigner';

const s3 = new S3Client({ region: 'ap-southeast-1' });
const BUCKET_NAME = 'my-app-uploads';

// Bước 1: Khởi tạo Multipart Upload và cấp link upload cho từng Chunk (mỗi chunk 10MB)
export async function initializeMultipartUpload(fileName: string, totalParts: number) {
  const fileKey = `videos/${crypto.randomUUID()}-${fileName}`;

  const createCommand = new CreateMultipartUploadCommand({
    Bucket: BUCKET_NAME,
    Key: fileKey
  });
  const { UploadId } = await s3.send(createCommand);

  // Sinh danh sách Presigned URLs cho Client upload thẳng lên S3
  const partUrls: string[] = [];
  for (let partNumber = 1; partNumber <= totalParts; partNumber++) {
    const uploadPartCommand = new UploadPartCommand({
      Bucket: BUCKET_NAME,
      Key: fileKey,
      UploadId,
      PartNumber: partNumber
    });
    // Link có thời hạn 1 giờ
    const signedUrl = await getSignedUrl(s3, uploadPartCommand, { expiresIn: 3600 });
    partUrls.push(signedUrl);
  }

  return { uploadId: UploadId, fileKey, partUrls };
}

