    Bucket: BUCKET_NAME,
    Key: fileKey
  });
  const { UploadId } = await s3.send(createCommand);

  // Sinh danh sách Presigned URLs cho Client upload thẳng lên S3
  const partUrls: string[] = [];
  for (let partNumber = 1; partNumber <= totalParts; partNumber++) {
    const uploadPartCommand = new UploadPartCommand({
      Bucket: BUCKET_NAME,
      Key: fileKey,
      UploadId,
      PartNumber: partNumber
    });
    // Link có thời hạn 1 giờ
    const signedUrl = await getSignedUrl(s3, uploadPartCommand, { expiresIn: 3600 });
    partUrls.push(signedUrl);
  }

  return { uploadId: UploadId, fileKey, partUrls };
}

