import sharp from 'sharp';
import { S3Client, GetObjectCommand } from '@aws-sdk/client-s3';

const s3 = new S3Client({ region: 'ap-southeast-1' });

export async function handleImageResizeOnDemand(imageKey: string, width: number, height: number, format: 'webp' | 'avif' | 'jpeg') {
  // 1. Tải ảnh gốc từ S3 Bucket
  const getCmd = new GetObjectCommand({ Bucket: 'my-original-images', Key: imageKey });
  const s3Response = await s3.send(getCmd);
  const originalBuffer = Buffer.from(await s3Response.Body!.transformToByteArray());

  // 2. Sử dụng thư viện native C++ (sharp) tối ưu hóa siêu tốc trong bộ nhớ
  const transformedBuffer = await sharp(originalBuffer)
    .resize(width, height, { fit: 'cover', position: 'center' })
    .toFormat(format, { quality: 80 })
    .toBuffer();

  // 3. Trả về cho CDN lưu cache với thời hạn vĩnh viễn (1 năm)
  return {
    statusCode: 200,
    headers: {
      'Content-Type': `image/${format}`,
      'Cache-Control': 'public, max-age=31536000, immutable'
    },
    body: transformedBuffer.toString('base64'),
    isBase64Encoded: true
  };
}

