import express, { Request, Response } from 'express';
import { Queue } from 'bullmq';

const app = express();
const exportQueue = new Queue('csv-exports');

// 1. Endpoint Tiếp nhận: Phản hồi tức thì (< 50ms), trả mã 202 Accepted
app.post('/api/v1/reports/orders/export', async (req: Request, res: Response) => {
  const jobId = crypto.randomUUID();
  const userId = req.headers['x-user-id'] as string;

  // Đẩy task vào hàng đợi BullMQ
  await exportQueue.add('export-csv-task', {
    jobId,
    userId,
    filters: req.body
  }, { jobId });

  const statusUrl = `/api/v1/jobs/${jobId}`;

  return res.status(202).json({
    status: 'QUEUED',
    message: 'Export request accepted. Processing in background.',
    jobId,
    statusCheckUrl: statusUrl
  });
});

// 2. Endpoint Polling kiểm tra trạng thái tiến trình
app.get('/api/v1/jobs/:jobId', async (req: Request, res: Response) => {
  const job = await exportQueue.getJob(req.params.jobId);
  if (!job) return res.status(404).json({ error: 'Job not found' });

  const state = await job.getState();
  const progress = job.progress;

  if (state === 'completed') {
    return res.json({
      status: 'COMPLETED',
      progress: 100,
      downloadUrl: job.returnvalue.s3PresignedUrl // S3 URL có thời hạn tải 24h
    });
  }

  return res.json({ status: state.toUpperCase(), progress });
});

