import { createServer } from 'http';
import { Server, Socket } from 'socket.io';
import { createClient } from 'redis';
import { createAdapter } from '@socket.io/redis-adapter';

const httpServer = createServer();
const io = new Server(httpServer, {
  cors: { origin: '*' }
});

// Kết nối Redis Pub/Sub để làm Backplane đồng bộ xuyên suốt các Pods
const pubClient = createClient({ url: 'redis://localhost:6379' });
const subClient = pubClient.duplicate();

async function bootstrap() {
  await Promise.all([pubClient.connect(), subClient.connect()]);

  // CỐT LÕI: Gắn Redis Adapter vào Socket.io
  // Giờ đây io.to('user_123').emit() sẽ tự động đồng bộ qua tất cả các server pods!
  io.adapter(createAdapter(pubClient, subClient));

  io.on('connection', (socket: Socket) => {
    const userId = socket.handshake.query.userId as string;
    if (userId) {
      // Cho socket tham gia vào Room riêng của chính User đó
      socket.join(`user:${userId}`);
      console.log(`User ${userId} connected and joined room user:${userId}`);
    }
  });

  httpServer.listen(3000);
}

// Bất kỳ pod nào cũng có thể gọi hàm này để bắn thông báo cho User B:
export function sendNotificationToUser(targetUserId: string, notification: any) {
  // Socket.io Redis Adapter tự động phát tán message sang đúng Pod đang giữ kết nối của targetUserId!
  io.to(`user:${targetUserId}`).emit('new_notification', notification);
}

bootstrap();

