// Triển khai Circuit Breaker bằng thư viện Opossum trong Node.js
import CircuitBreaker from 'opossum';

async function callThirdPartyPaymentApi(orderData: any) {
  const response = await fetch('https://payment-gateway.internal/charges', {
    method: 'POST',
    body: JSON.stringify(orderData),
    signal: AbortSignal.timeout(3000) // 3s timeout
  });
  if (!response.ok) throw new Error(`Payment failed: ${response.status}`);
  return await response.json();
}

// Cấu hình Circuit Breaker
const breakerOptions = {
  timeout: 3000,              // Nếu gọi quá 3s coi như thất bại
  errorThresholdPercentage: 50, // Nếu 50% request bị lỗi trong window -> NGẮT MẠCH!
  resetTimeout: 30000          // Sau 30s thử chuyển sang Half-Open để kiểm tra lại
};

export const paymentBreaker = new CircuitBreaker(callThirdPartyPaymentApi, breakerOptions);

// Hàm Fallback khi mạch đang BUNG (OPEN)
paymentBreaker.fallback(() => {
  console.warn('[CIRCUIT OPEN] Payment Gateway is down. Returning graceful fallback.');
  return { status: 'QUEUED_FOR_LATER', message: 'Hệ thống thanh toán đang bảo trì, đơn hàng của bạn đã được ghi nhận.' };
});

paymentBreaker.on('open', () => console.error('🚨 [CIRCUIT BREAKER] State changed to OPEN!'));
paymentBreaker.on('halfOpen', () => console.log('⚠️ [CIRCUIT BREAKER] State changed to HALF-OPEN.'));
paymentBreaker.on('close', () => console.log('✅ [CIRCUIT BREAKER] Downstream recovered. State CLOSED.'));

