import Redis from 'ioredis';
import { Pool } from 'pg';

const redis = new Redis();
const pool = new Pool();

export async function getProductDetailsSafe(productId: string) {
  const cacheKey = `product:${productId}`;
  const lockKey = `lock:product:${productId}`;

  // 1. Kiểm tra Cache
  const cached = await redis.get(cacheKey);
  if (cached) {
    return JSON.parse(cached);
  }

  // 2. CACHE STAMPEDE DEFENSE: Dùng Redis Mutex Lock để chỉ cho phép 1 request vào DB
  const acquiredLock = await redis.set(lockKey, 'LOCKED', 'EX', 10, 'NX');

  if (!acquiredLock) {
    // Không lấy được lock nghĩa là ĐÃ CÓ request khác đang đi lấy dữ liệu từ DB
    // Ngủ 50ms rồi thử đọc lại từ Cache
    await new Promise(r => setTimeout(r, 50));
    return getProductDetailsSafe(productId);
  }

  try {
    console.log(`[DB QUERY] Fetching product ${productId} from database...`);
    const { rows } = await pool.query('SELECT * FROM products WHERE id = $1', [productId]);
    const product = rows[0] || null;

    // 3. TTL + JITTER: Tránh việc hàng loạt sản phẩm cùng hết hạn vào đúng 1 thời điểm
    const baseTtl = 3600; // 1 giờ
    const jitter = Math.floor(Math.random() * 300); // Thêm ngẫu nhiên 0-300 giây
    await redis.set(cacheKey, JSON.stringify(product), 'EX', baseTtl + jitter);

    return product;
  } finally {
    // Giải phóng lock
    await redis.del(lockKey);
  }
}

