import crypto from 'crypto';

// Triển khai mô hình Consistent Hashing với Virtual Nodes cơ bản
export class ConsistentHashRing {
  private ring: Map<number, string> = new Map();
  private sortedKeys: number[] = [];
  private vnodes: number;

  constructor(vnodes: number = 100) {
    this.vnodes = vnodes;
  }

  private hash(val: string): number {
    const hex = crypto.createHash('md5').update(val).digest('hex');
    return parseInt(hex.substring(0, 8), 16);
  }

  public addNode(node: string) {
    for (let i = 0; i < this.vnodes; i++) {
      const vnodeKey = `${node}#${i}`;
      const hashVal = this.hash(vnodeKey);
      this.ring.set(hashVal, node);
      this.sortedKeys.push(hashVal);
    }
    this.sortedKeys.sort((a, b) => a - b);
  }

  public getNode(key: string): string | null {
    if (this.ring.size === 0) return null;
    const hashVal = this.hash(key);

    // Tìm kiếm nhị phân node đầu tiên có hash >= hash của key (Đi theo chiều kim đồng hồ)
    for (const nodeHash of this.sortedKeys) {
      if (nodeHash >= hashVal) {
        return this.ring.get(nodeHash)!;
      }
    }
    // Nếu vượt quá giá trị lớn nhất, quay tròn về node đầu tiên của vòng
    return this.ring.get(this.sortedKeys[0])!;
  }
}

