      const hashVal = this.hash(vnodeKey);
      this.ring.set(hashVal, node);
      this.sortedKeys.push(hashVal);
    }
    this.sortedKeys.sort((a, b) => a - b);
  }

  public getNode(key: string): string | null {
    if (this.ring.size === 0) return null;
    const hashVal = this.hash(key);

    // Tìm kiếm nhị phân node đầu tiên có hash >= hash của key (Đi theo chiều kim đồng hồ)
    for (const nodeHash of this.sortedKeys) {
      if (nodeHash >= hashVal) {
        return this.ring.get(nodeHash)!;
      }
    }
    // Nếu vượt quá giá trị lớn nhất, quay tròn về node đầu tiên của vòng
    return this.ring.get(this.sortedKeys[0])!;
  }
}

