import crypto from 'crypto';

const redis = new Redis();

// LUA SCRIPT GIẢI PHÓNG KHÓA NGUYÊN TỬ VÀ AN TOÀN TUYỆT ĐỐI
const RELEASE_LOCK_LUA_SCRIPT = `
  if redis.call("get", KEYS[1]) == ARGV[1] then
    return redis.call("del", KEYS[1])
  else
    return 0
  end
`;

export async function executeWithDistributedLock<T>(
  lockName: string,
  ttlMs: number,
  task: () => Promise<T>
): Promise<T | null> {
  const lockKey = `dlock:${lockName}`;
  const lockValue = crypto.randomUUID(); // Token định danh duy nhất của Pod này

  // 1. Acquire Lock nguyên tử bằng SET NX PX
  const acquired = await redis.set(lockKey, lockValue, 'PX', ttlMs, 'NX');
  if (!acquired) {
    console.warn(`Could not acquire lock for ${lockName}. Another instance is running.`);
    return null;
  }

  try {
    console.log(`[LOCK ACQUIRED] Running task for ${lockName}...`);
    return await task();
  } finally {
    // 2. Giải phóng khóa an toàn bằng Lua Script (Chỉ xóa nếu đúng token của mình!)
    await redis.eval(RELEASE_LOCK_LUA_SCRIPT, 1, lockKey, lockValue);
    console.log(`[LOCK RELEASED] Lock for ${lockName} released cleanly.`);
  }
}

