// Minh họa Saga Orchestrator cho luồng Đặt hàng (Order Flow)
interface SagaStep {
  name: string;
  forward: () => Promise<void>;    // Thao tác chính
  compensate: () => Promise<void>; // Thao tác Bù trừ (BẮT BUỘC PHẢI IDEMPOTENT)
}

export class OrderSagaOrchestrator {
  private completedSteps: SagaStep[] = [];

  async run(steps: SagaStep[]): Promise<boolean> {
    for (const step of steps) {
      try {
        console.log(`[SAGA FORWARD] Executing: ${step.name}`);
        await step.forward();
        this.completedSteps.push(step);
      } catch (err: any) {
        console.error(`[SAGA ERROR] Step ${step.name} failed: ${err.message}. Initiating rollback...`);
        await this.rollback();
        return false;
      }
    }
    console.log('[SAGA SUCCESS] All steps completed successfully!');
    return true;
  }

  private async rollback(): Promise<void> {
    // Chạy ngược lại danh sách các bước đã thành công để bù trừ
    const stepsToUndo = [...this.completedSteps].reverse();
    for (const step of stepsToUndo) {
      console.warn(`[SAGA COMPENSATE] Rolling back step: ${step.name}`);
      try {
        await step.compensate();
      } catch (compErr: any) {
        console.error(`🚨 [CRITICAL SAGA FAILURE] Compensation for ${step.name} failed! Alerting support team...`);
        // Ghi log vào bảng sự cố để kỹ sư can thiệp thủ công
      }
    }
  }
}

