// Minh họa xử lý Resumable Chunked Upload theo tư duy TUS Protocol
import express, { Request, Response } from 'express';
import fs from 'fs';
import path from 'path';

const app = express();
const UPLOAD_DIR = '/tmp/resumable_uploads';

// 1. Kiểm tra trạng thái hiện tại của file (Hỏi offset đã nhận)
app.head('/api/v1/files/:uploadId', (req: Request, res: Response) => {
  const filePath = path.join(UPLOAD_DIR, req.params.uploadId);
  if (!fs.existsSync(filePath)) {
    return res.status(404).end();
  }
  const stats = fs.statSync(filePath);
  // Trả về số byte server ĐÃ THỰC SỰ LƯU TRÊN ĐĨA
  res.setHeader('Upload-Offset', stats.size.toString());
  return res.status(200).end();
});

// 2. Tiếp nhận Chunk dữ liệu tiếp theo bằng PATCH
app.patch('/api/v1/files/:uploadId', express.raw({ type: 'application/offset+octet-stream', limit: '20mb' }), (req: Request, res: Response) => {
  const uploadId = req.params.uploadId;
  const clientOffset = parseInt(req.headers['upload-offset'] as string, 10);
  const filePath = path.join(UPLOAD_DIR, uploadId);

  const currentSize = fs.existsSync(filePath) ? fs.statSync(filePath).size : 0;

  // Kiểm tra tính toàn vẹn: Offset của client gửi lên bắt buộc phải khớp với dung lượng hiện có trên server
  if (clientOffset !== currentSize) {
    return res.status(409).json({ error: `Offset mismatch. Server has ${currentSize}, client sent ${clientOffset}` });
  }

  // Ghi nối tiếp (Append) dữ liệu chunk mới vào cuối file
  fs.appendFileSync(filePath, req.body);
  const newSize = fs.statSync(filePath).size;

  res.setHeader('Upload-Offset', newSize.toString());
  return res.status(204).end();
});

