import { PoolClient } from 'pg';

interface WebhookPaymentPayload {
  transactionId: string; // Mã giao dịch của cổng thanh toán (Natural Key)
  orderId: string;
  amount: number;
  status: 'SUCCESS' | 'FAILED';
}

export async function processPaymentWebhookSafely(client: PoolClient, payload: WebhookPaymentPayload) {
  try {
    await client.query('BEGIN');

    // 1. DEDUP BẰNG BẢNG PROCESSED_PAYMENTS (Chống cộng tiền 2 lần tuyệt đối)
    const dedupQuery = `
      INSERT INTO processed_payment_events (transaction_id, order_id, amount, processed_at)
      VALUES ($1, $2, $3, NOW())
      ON CONFLICT (transaction_id) DO NOTHING
      RETURNING transaction_id;
    `;
    const dedupRes = await client.query(dedupQuery, [payload.transactionId, payload.orderId, payload.amount]);

    if (dedupRes.rows.length === 0) {
      console.warn(`[IDEMPOTENT] Giao dịch ${payload.transactionId} đã được xử lý trước đó. Bỏ qua!`);
      await client.query('COMMIT');
      return { status: 'ALREADY_PROCESSED' };
    }

    // 2. ATOMIC STATE UPDATE TRÊN ĐƠN HÀNG
    // Chỉ cập nhật nếu đơn hàng thực sự đang ở trạng thái PENDING
    const updateOrderQuery = `
      UPDATE orders
      SET status = 'PAID', paid_amount = $1, updated_at = NOW()
      WHERE id = $2 AND status = 'PENDING'
      RETURNING id, customer_id;
    `;
    const orderRes = await client.query(updateOrderQuery, [payload.amount, payload.orderId]);

    if (orderRes.rows.length === 0) {
      console.warn(`Đơn hàng ${payload.orderId} không ở trạng thái PENDING. Có thể đã bị hủy hoặc xử lý trước.`);
    } else {
      // 3. Cộng quyền lợi / Xuất hàng cho khách hàng trong cùng Transaction
      const customerId = orderRes.rows[0].customer_id;
      await client.query('UPDATE users SET is_vip = TRUE WHERE id = $1', [customerId]);
    }

    await client.query('COMMIT');
    return { status: 'SUCCESS' };
  } catch (err) {
    await client.query('ROLLBACK');
    throw err;
  }
}

