import Redis from 'ioredis';

const redis = new Redis();

// LUA SCRIPT CHỐNG BÁN VƯỢT NGUYÊN TỬ (Atomic Anti-Oversell Script)
const FLASH_SALE_LUA_SCRIPT = `
  local stock_key = KEYS[1]
  local users_key = KEYS[2]
  local user_id = ARGV[1]

  -- 1. Kiểm tra xem người dùng này đã mua thành công trước đó chưa
  if redis.call("SISMEMBER", users_key, user_id) == 1 then
    return -1 -- Lỗi: Mỗi khách hàng chỉ được mua 1 suất duy nhất!
  end

  -- 2. Kiểm tra số lượng tồn kho hiện tại trong RAM
  local current_stock = tonumber(redis.call("GET", stock_key) or "0")
  if current_stock <= 0 then
    return 0 -- Lỗi: Đã hết hàng hoàn toàn!
  end

  -- 3. Trừ tồn kho và đánh dấu user đã mua nguyên tử
  redis.call("DECR", stock_key)
  redis.call("SADD", users_key, user_id)
  return 1 -- Thành công! Giữ chỗ thành công!
`;

export async function attemptBuyFlashSale(saleId: string, userId: string): Promise<{ success: boolean; message: string }> {
  const stockKey = `flashsale:${saleId}:stock`;
  const usersKey = `flashsale:${saleId}:buyers`;

  // Thực thi Lua Script siêu tốc trên bộ nhớ RAM của Redis (< 1ms)
  const result = await redis.eval(FLASH_SALE_LUA_SCRIPT, 2, stockKey, usersKey, userId) as number;

  if (result === 1) {
    // THÀNH CÔNG: Đẩy vào Queue để ghi Database sau
    // await orderQueue.add('create-order', { saleId, userId });
    return { success: true, message: 'Chúc mừng bạn đã săn vé thành công! Đang tạo đơn...' };
  } else if (result === -1) {
    return { success: false, message: 'Bạn đã tham gia mua sản phẩm này rồi.' };
  } else {
    return { success: false, message: 'Rất tiếc, sản phẩm đã hết suất!' };
  }
}

