// Minh họa 3 nhóm GoF Patterns trong Backend TypeScript:

// 1. CREATIONAL (Builder Pattern: Khởi tạo đối tượng phức tạp có kiểm soát)
class DatabaseConfigBuilder {
  private host: string = 'localhost';
  private port: number = 5432;
  setHost(h: string) { this.host = h; return this; }
  setPort(p: number) { this.port = p; return this; }
  build() { return { host: this.host, port: this.port }; }
}

// 2. STRUCTURAL (Adapter Pattern: Bọc API của bên thứ 3 về chuẩn chung của hệ thống)
interface PaymentProcessor {
  charge(amount: number): Promise<void>;
}
class StripeLegacySdk { makeCharge(cents: number) { /*...*/ } }
class StripeAdapter implements PaymentProcessor {
  constructor(private stripe: StripeLegacySdk) {}
  async charge(amount: number) {
    this.stripe.makeCharge(amount * 100);
  }
}

// 3. BEHAVIORAL (Strategy Pattern: Thay đổi thuật toán chiết khấu động lúc runtime)
interface DiscountStrategy { calculate(price: number): number; }
class VipDiscount implements DiscountStrategy { calculate(p: number) { return p * 0.8; } }
class RegularDiscount implements DiscountStrategy { calculate(p: number) { return p; } }

