// 1. Single Responsibility (SRP): Tách riêng phần gửi thông báo ra khỏi nghiệp vụ đơn hàng
interface NotificationSender {
  send(message: string): Promise<void>;
}

// 2. Open/Closed (OCP): Thêm phương thức thanh toán mới mà KHÔNG CẦN SỬA code OrderService cũ
interface PaymentMethod {
  pay(amount: number): Promise<boolean>;
}
class MomoPayment implements PaymentMethod {
  async pay(amount: number) { return true; }
}
class ZaloPayPayment implements PaymentMethod { // Thêm mới thoải mái!
  async pay(amount: number) { return true; }
}

// 3. Dependency Inversion (DIP): OrderService cấp cao CHỈ PHỤ THUỘC vào Interface trừu tượng
export class OrderService {
  constructor(
    private paymentMethod: PaymentMethod,       // Injected interface
    private notifier: NotificationSender        // Injected interface
  ) {}

  async checkout(orderId: string, amount: number) {
    const success = await this.paymentMethod.pay(amount);
    if (success) {
      await this.notifier.send(`Đơn hàng ${orderId} đã thanh toán thành công!`);
    }
  }
}

