export class DatabaseConnectionSingleton {
  private static instance: DatabaseConnectionSingleton | null = null;
  private connectionId: string;

  // BẮT BUỘC: Private constructor chặn việc dùng từ khóa 'new' từ bên ngoài
  private constructor() {
    this.connectionId = 'conn_' + crypto.randomUUID();
    console.log(`[DB] Khởi tạo kết nối duy nhất: ${this.connectionId}`);
  }

  // Điểm truy cập toàn cầu
