interface NotificationSender {
  send(recipient: string, message: string): Promise<void>;
}

// 2. Các Concrete Classes cụ thể
class EmailSender implements NotificationSender {
  async send(recipient: string, message: string) { console.log(`[EMAIL] to ${recipient}: ${message}`); }
}
class SmsSender implements NotificationSender {
  async send(recipient: string, message: string) { console.log(`[SMS] to ${recipient}: ${message}`); }
}
class PushSender implements NotificationSender {
  async send(recipient: string, message: string) { console.log(`[PUSH] to ${recipient}: ${message}`); }
}

// 3. FACTORY METHOD: Đóng gói toàn bộ logic khởi tạo
export class NotificationFactory {
  static createSender(channel: 'EMAIL' | 'SMS' | 'PUSH'): NotificationSender {
    switch (channel) {
      case 'EMAIL': return new EmailSender();
      case 'SMS':   return new SmsSender();
      case 'PUSH':  return new PushSender();
      default: throw new Error(`Unsupported notification channel: ${channel}`);
    }
  }
}

// 4. Sử dụng trong Service (Không phụ thuộc vào class cụ thể nào)
export async function notifyUser(channel: 'EMAIL' | 'SMS' | 'PUSH', target: string, text: string) {
  const sender = NotificationFactory.createSender(channel);
  await sender.send(target, text);
}

