import { Worker, Queue } from 'bullmq';

const mainQueue = new Queue('order-processing');
const deadLetterQueue = new Queue('order-dlq'); // HÀNG ĐỢI DEAD LETTER

const orderWorker = new Worker('order-processing', async (job) => {
  // Logic xử lý đơn hàng...
  if (job.data.invalidPayload) {
    throw new Error('Malformed payload: Cannot process order');
  }
  console.log(`Order ${job.id} processed successfully.`);
}, {
  connection: { host: 'localhost', port: 6379 }
});

// LẮNG NGHE SỰ KIỆN THẤT BẠI: Khi vượt quá số lần retry cho phép -> CHUYỂN VÀO DLQ
orderWorker.on('failed', async (job, err) => {
  if (job && job.attemptsMade >= (job.opts.attempts || 3)) {
    console.error(`🚨 [POISON PILL] Job ${job.id} exceeded max retries. Moving to DLQ!`);

    await deadLetterQueue.add('dead-letter-job', {
      originalJobId: job.id,
      originalData: job.data,
      failedReason: err.message,
      failedAt: new Date().toISOString()
    });
  }
});

