import amqp from 'amqplib';

// Khởi tạo kết nối và gửi tin nhắn qua RabbitMQ
export async function sendTaskToRabbitMQ(queueName: string, taskData: any) {
  const connection = await amqp.connect('amqp://localhost');
  const channel = await connection.createChannel();

  // Đảm bảo Queue tồn tại và có tính bền bỉ (durable: true để không mất khi restart server)
  await channel.assertQueue(queueName, { durable: true });

  const messageBuffer = Buffer.from(JSON.stringify(taskData));

  // persistent: true báo cho RabbitMQ ghi message xuống đĩa an toàn
  channel.sendToQueue(queueName, messageBuffer, { persistent: true });
  console.log(`[RABBITMQ] Task dispatched to ${queueName}`);

  await channel.close();
  await connection.close();
}

