// Minh họa kiến trúc Retry bằng DLX + TTL trong RabbitMQ:
//
//               [Main Queue] ──(Lỗi: Chuyển sang Retry Queue)──┐
//                    ▲                                         │
//                    │ (Hết hạn TTL 5s: Tự rơi về Main Queue)  ▼
//             [Retry Exchange] ◄────────────── [Retry Queue (TTL: 5000ms)]
//                                              (Không có ai lắng nghe)

import amqp from 'amqplib';

export async function setupRetryTopology(channel: amqp.Channel) {
  // 1. Tạo Exchange chính và Queue chính
  await channel.assertExchange('main_exchange', 'direct');
  await channel.assertQueue('main_queue', {
    durable: true,
    deadLetterExchange: 'retry_exchange' // Nếu NACK không requeue -> rơi sang retry_exchange
  });
  await channel.bindQueue('main_queue', 'main_exchange', 'task_key');

  // 2. Tạo Retry Queue với Message TTL (Nơi tạm giữ message để chờ đợi)
  await channel.assertExchange('retry_exchange', 'direct');
  await channel.assertQueue('retry_wait_5s_queue', {
    durable: true,
    messageTtl: 5000, // Tự động chết sau 5 giây!
