import Redis from 'ioredis';
import { Pool } from 'pg';

const redis = new Redis();
const pool = new Pool();

export class CacheAsideProductService {
  // CHIẾN LƯỢC ĐỌC: Cache-Aside (Lazy Loading)
  async getProduct(productId: string) {
    const cacheKey = `product:${productId}`;

    // 1. Đọc từ Cache
    const cached = await redis.get(cacheKey);
    if (cached) return JSON.parse(cached);

    // 2. Cache Miss: Đọc từ Database
    const { rows } = await pool.query('SELECT * FROM products WHERE id = $1', [productId]);
    const product = rows[0];

    // 3. Nạp vào Cache kèm TTL
    if (product) {
      await redis.set(cacheKey, JSON.stringify(product), 'EX', 3600); // 1 hour TTL
    }
    return product;
  }

  // CHIẾN LƯỢC GHI & VÔ HIỆU HÓA: Cập nhật DB rồi XÓA Cache
  async updateProductPrice(productId: string, newPrice: number) {
    // 1. Cập nhật Source of Truth trong Database trước
    await pool.query('UPDATE products SET price = $1, updated_at = NOW() WHERE id = $2', [newPrice, productId]);

    // 2. VÔ HIỆU HÓA CHUẨN XÁC: Xóa key khỏi Redis (Tuyệt đối không update đè!)
    const cacheKey = `product:${productId}`;
    await redis.del(cacheKey);
    console.log(`Cache invalidated for ${cacheKey}`);
  }
}

