import express, { Request, Response, NextFunction } from 'express';
import jwt from 'jsonwebtoken';

const app = express();
const JWT_SECRET = process.env.JWT_SECRET || 'super_secret_signing_key';

export interface AuthenticatedUser {
  userId: string;
  role: 'ADMIN' | 'CUSTOMER';
}

// 1. AUTHENTICATION MIDDLEWARE: Xác minh danh tính ("Bạn là ai?")
export function authenticateToken(req: Request, res: Response, next: NextFunction) {
  const authHeader = req.headers.authorization;
  const token = authHeader && authHeader.split(' ')[1]; // Format: Bearer <token>

  if (!token) {
    return res.status(401).json({ error: 'Unauthorized: Missing token' });
  }

  // Tự động verify chữ ký Cryptographic Signature và kiểm tra 'exp' claim
  jwt.verify(token, JWT_SECRET, (err, decoded) => {
    if (err) {
      return res.status(401).json({ error: 'Unauthorized: Invalid or expired token' });
    }
    // Gán thông tin danh tính đã được xác thực vào request
    (req as any).user = decoded as AuthenticatedUser;
    next();
  });
}

// 2. AUTHORIZATION MIDDLEWARE: Kiểm tra quyền hạn ("Bạn được làm gì?")
export function requireRole(requiredRole: 'ADMIN' | 'CUSTOMER') {
  return (req: Request, res: Response, next: NextFunction) => {
    const user = (req as any).user as AuthenticatedUser;
    if (!user || user.role !== requiredRole) {
      // 403 Forbidden: Đã biết bạn là ai nhưng bạn KHÔNG ĐỦ QUYỀN vào đây!
      return res.status(403).json({ error: 'Forbidden: Insufficient permissions' });
    }
    next();
  };
}

