import express, { Request, Response } from 'express';
import jwt from 'jsonwebtoken';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const ACCESS_SECRET = 'access_secret_key_15m';
const REFRESH_SECRET = 'refresh_secret_key_7d';

// Database giả lập lưu trữ các Refresh Token hợp lệ của user (phục vụ Rotation)
const activeRefreshTokens = new Map<string, { userId: string; familyId: string }>();

app.post('/api/v1/auth/refresh', async (req: Request, res: Response) => {
  // 1. Đọc Refresh Token an toàn từ HttpOnly Cookie
  const oldRefreshToken = req.cookies?.refreshToken;
  if (!oldRefreshToken) return res.status(401).json({ error: 'Missing refresh token' });

  try {
    const payload = jwt.verify(oldRefreshToken, REFRESH_SECRET) as { userId: string; tokenId: string; familyId: string };

    // 2. REUSE DETECTION: Kiểm tra xem token này còn trong danh sách hợp lệ không
    const tokenRecord = activeRefreshTokens.get(payload.tokenId);
    if (!tokenRecord) {
      // 🚨 CẢNH BÁO NGUY HIỂM: Token đã bị dùng rồi mà lại xuất hiện lại -> BỊ HACKER ĐÁNH CẮP!
      console.error(`[SECURITY BREACH] Refresh token reuse detected for User ${payload.userId}! Revoking all sessions.`);
      // HỦY TOÀN BỘ các token thuộc họ (family) này của user ngay lập tức!
      activeRefreshTokens.clear();
      return res.status(403).json({ error: 'Security breach detected. Please login again.' });
    }

    // 3. TOKEN ROTATION: Xóa token cũ ngay lập tức
    activeRefreshTokens.delete(payload.tokenId);

    // 4. Cấp Access Token mới (15 phút) và Refresh Token mới (7 ngày)
    const newAccessToken = jwt.sign({ userId: payload.userId }, ACCESS_SECRET, { expiresIn: '15m' });
    const newTokenId = crypto.randomUUID();
    const newRefreshToken = jwt.sign({ userId: payload.userId, tokenId: newTokenId, familyId: payload.familyId }, REFRESH_SECRET, { expiresIn: '7d' });

    // Lưu token mới vào DB
    activeRefreshTokens.set(newTokenId, { userId: payload.userId, familyId: payload.familyId });

    // 5. Ghi Refresh Token mới vào HttpOnly Cookie
    res.cookie('refreshToken', newRefreshToken, {
      httpOnly: true, // Chống XSS đọc trộm
      secure: true,   // Chỉ gửi qua HTTPS
      sameSite: 'strict', // Chống CSRF
      path: '/api/v1/auth/refresh' // Chỉ gửi cookie khi gọi endpoint refresh
    });

    return res.json({ accessToken: newAccessToken });
  } catch (err) {
    return res.status(401).json({ error: 'Invalid or expired refresh token' });
  }
});

