// Flow tạo và xác minh Reset Password Token an toàn trong Node.js (TypeScript)
import crypto from 'node:crypto';
import bcrypt from 'bcrypt';
import { db } from './database';

// 1. Tạo Reset Token khi người dùng yêu cầu quên mật khẩu
export async function requestPasswordReset(email: string): Promise<void> {
  const user = await db.user.findUnique({ where: { email } });

  // LUÔN return thành công dù email không tồn tại để chống User Enumeration
  if (!user) return;

  // Sinh 32 bytes ngẫu nhiên bảo mật cao (64 hex characters)
  const rawResetToken = crypto.randomBytes(32).toString('hex');

  // CHỈ LƯU BẢN HASH SHA-256 vào Database, không lưu raw token
  const tokenHash = crypto.createHash('sha256').update(rawResetToken).digest('hex');
  const expiresAt = new Date(Date.now() + 15 * 60 * 1000); // 15 phút TTL

  await db.passwordReset.upsert({
    where: { userId: user.id },
    create: { userId: user.id, tokenHash, expiresAt, isUsed: false },
    update: { tokenHash, expiresAt, isUsed: false }
  });

  // Gửi rawResetToken qua email (thực tế push vào hàng đợi gửi mail)
  const resetLink = `https://app.example.com/reset-password?token=${rawResetToken}&email=${encodeURIComponent(email)}`;
  await emailQueue.add('send-reset-email', { to: email, resetLink });
}

// 2. Xác thực và đổi mật khẩu mới
export async function confirmPasswordReset(rawToken: string, newPassword: string): Promise<void> {
  const tokenHash = crypto.createHash('sha256').update(rawToken).digest('hex');

  await db.$transaction(async (tx) => {
    const record = await tx.passwordReset.findFirst({
      where: {
        tokenHash,
        isUsed: false,
        expiresAt: { gt: new Date() }
      }
    });

    if (!record) {
      throw new Error('Reset link không hợp lệ hoặc đã hết hạn.');
    }

    const hashedPassword = await bcrypt.hash(newPassword, 12);

    // Cập nhật mật khẩu & đánh dấu token đã dùng (Single-use)
    await tx.user.update({
      where: { id: record.userId },
      data: { password: hashedPassword }
    });

    await tx.passwordReset.update({
      where: { id: record.id },
      data: { isUsed: true }
    });

    // BẮT BUỘC: Thu hồi toàn bộ Session và Refresh Token cũ của user
    await tx.refreshToken.deleteMany({ where: { userId: record.userId } });
  });
}

