// Middleware bảo vệ Login chống Brute-Force bằng Redis đa tầng (Node.js/ioredis)
import { Request, Response, NextFunction } from 'express';
import Redis from 'ioredis';

const redis = new Redis(process.env.REDIS_URL!);

export async function bruteForceGuard(req: Request, res: Response, next: NextFunction) {
  const clientIp = req.ip || req.socket.remoteAddress;
  const email = req.body.email?.toLowerCase().trim();

  if (!email) {
    return res.status(400).json({ error: 'Email là bắt buộc' });
  }

  const ipKey = `rl:ip:${clientIp}`;
  const accountKey = `rl:acc:${email}`;

  // Kiểm tra 1: IP có đang bị chặn vì spam không (Max 30 req/phút)
  const ipAttempts = await redis.get(ipKey);
  if (ipAttempts && parseInt(ipAttempts, 10) > 30) {
    return res.status(429).json({ error: 'Quá nhiều request từ mạng của bạn. Vui lòng thử lại sau.' });
  }

  // Kiểm tra 2: Tài khoản có bị soft-lock do đăng nhập sai nhiều lần không
  const failedAttempts = await redis.get(accountKey);
  const count = failedAttempts ? parseInt(failedAttempts, 10) : 0;

  if (count >= 5) {
    const ttl = await redis.ttl(accountKey);
    return res.status(423).json({
      error: `Tài khoản tạm thời bị khóa do nhập sai quá nhiều lần. Vui lòng thử lại sau ${ttl} giây.`
    });
  }

  // Gắn helper vào request để Auth Handler gọi khi verify mật khẩu THẤT BẠI
  req.recordFailedLogin = async () => {
    // Tăng đếm IP (hết hạn 60s)
    await redis.multi()
      .incr(ipKey)
      .expire(ipKey, 60)
      // Tăng đếm Account (hết hạn 15 phút)
      .incr(accountKey)
      .expire(accountKey, 15 * 60)
      .exec();
  };

  // Helper xóa đếm khi đăng nhập THÀNH CÔNG
  req.clearFailedLogin = async () => {
    await redis.del(accountKey);
  };

  return next();
}

