// Thiết lập HttpOnly Cookie bảo mật cao trên Express.js / NestJS
import express, { Response } from 'express';

export function setAuthCookies(res: Response, refreshToken: string) {
  res.cookie('refresh_token', refreshToken, {
    httpOnly: true,                 // CỰC KỲ QUAN TRỌNG: Chặn JavaScript đọc trộm token (Chống XSS)
    secure: process.env.NODE_ENV === 'production', // Chỉ gửi qua giao thức HTTPS
    sameSite: 'lax',                // Chống CSRF: Trình duyệt không gửi cookie trong cross-site POST
    path: '/api/v1/auth/refresh',   // Thu hẹp phạm vi: Cookie chỉ tự động gửi khi gọi endpoint refresh
    maxAge: 7 * 24 * 60 * 60 * 1000 // Hạn dùng 7 ngày
  });
}

// Khi người dùng Logout
export function clearAuthCookies(res: Response) {
  res.clearCookie('refresh_token', {
    httpOnly: true,
    secure: process.env.NODE_ENV === 'production',
    sameSite: 'lax',
    path: '/api/v1/auth/refresh'
  });
}

