import { Pool } from 'pg';
const pool = new Pool();

// ❌ LỖ HỔNG NGUY HIỂM: Nối chuỗi trực tiếp (String Concatenation)
// Input: userInput = "admin' OR '1'='1" -> Câu lệnh bypass đăng nhập hoàn toàn!
export async function vulnerableLogin(username: string, pass: string) {
  const query = `SELECT * FROM users WHERE username = '${username}' AND password = '${pass}'`;
  return await pool.query(query); // Hacker dump toàn bộ bảng users!
}

