export async function secureLogin(username: string) {
  const query = `SELECT id, password_hash, role FROM users WHERE username = $1 LIMIT 1`;
  // DB Driver truyền username vào dưới dạng literal value, không thể thay đổi AST
  const result = await pool.query(query, [username]);
  return result.rows[0];
}

