// Prisma/TypeORM/Drizzle vẫn dính SQLi nếu nối chuỗi vào raw column name
export async function safeDynamicSort(sortBy: string, order: 'ASC' | 'DESC') {
  // BẮT BUỘC: Whitelist các cột được phép sắp xếp
  const ALLOWED_COLUMNS = ['created_at', 'price', 'views'] as const;
  if (!ALLOWED_COLUMNS.includes(sortBy as any)) {
    throw new Error('Cột sắp xếp không hợp lệ');
  }

  // An toàn vì sortBy đã qua Whitelist nghiêm ngặt
  return await pool.query(`SELECT * FROM products ORDER BY ${sortBy} ${order === 'DESC' ? 'DESC' : 'ASC'}`);
}

