// Phòng chống CSRF bằng csurf middleware và Custom Header Verification trên Express
import express from 'express';
import cookieParser from 'cookie-parser';
import crypto from 'crypto';

const app = express();
app.use(cookieParser('cookie-secret'));
app.use(express.json());

// Cách 1: Xác thực Header Origin/Referer cho API
export function verifyOriginMiddleware(req: express.Request, res: express.Response, next: express.NextFunction) {
  // Chỉ kiểm tra các phương thức thay đổi dữ liệu
  if (['POST', 'PUT', 'PATCH', 'DELETE'].includes(req.method)) {
    const origin = req.headers['origin'] || req.headers['referer'];
    const allowedHost = 'https://app.mybank.com';

    if (!origin || !origin.toString().startsWith(allowedHost)) {
      return res.status(403).json({ error: 'CSRF Protection: Invalid Request Origin' });
    }
  }
  return next();
}

// Cách 2: Thiết lập Cookie với SameSite=Strict kết hợp Anti-CSRF Token
app.post('/api/v1/auth/login', (req, res) => {
  // 1. Session Cookie với SameSite
  res.cookie('session_id', 'sess_secure_xyz', {
    httpOnly: true,
    secure: true,
    sameSite: 'strict', // Trình duyệt không bao giờ gửi cookie từ site ngoài
    path: '/'
  });

  // 2. Sinh CSRF token gửi về cho Client gắn vào Header request tiếp theo
  const csrfToken = crypto.randomBytes(24).toString('hex');
  res.cookie('XSRF-TOKEN', csrfToken, {
    secure: true,
    sameSite: 'strict',
    httpOnly: false // Cho phép JS đọc để đưa vào header X-CSRF-Token
  });

  return res.json({ message: 'Login successful' });
});

