// Quản lý mật khẩu chuẩn mực bằng Argon2id (Chuẩn bảo mật hiện đại nhất)
import argon2 from 'argon2';

// 1. Băm mật khẩu khi người dùng đăng ký hoặc đổi mật khẩu
export async function hashPassword(plainPassword: string): Promise<string> {
  return await argon2.hash(plainPassword, {
    type: argon2.argon2id,  // Kết hợp chống Side-channel attack và GPU brute-force
    memoryCost: 65536,      // Tốn 64 MB RAM cho mỗi lần băm (chống ASIC/GPU)
    timeCost: 3,            // 3 vòng lặp tính toán
    parallelism: 4          // 4 luồng song song
  });
  // Output chứa cả Salt, Params và Hash: $argon2id$v=19$m=65536,t=3,p=4$...
}

// 2. Xác thực mật khẩu khi người dùng đăng nhập
export async function verifyPassword(storedHash: string, inputPassword: string): Promise<boolean> {
  try {
    // Tự động kiểm tra constant-time và so khớp
    const isCorrect = await argon2.verify(storedHash, inputPassword);

    // Kiểm tra xem cấu hình băm trong DB có bị lỗi thời cần nâng cấp (rehash) không
    if (isCorrect && argon2.needsRehash(storedHash, { memoryCost: 65536, timeCost: 3 })) {
      console.log('Cần re-hash mật khẩu lên chuẩn bảo mật mới hơn');
    }

    return isCorrect;
  } catch (err) {
    return false;
  }
}

