// file: /etc/nginx/conf.d/secure-api.conf

server {
    listen 443 ssl http2;
    server_name api.example.com;

    # Chứng chỉ số cấp bởi Certificate Authority (Let's Encrypt / DigiCert)
    ssl_certificate /etc/letsencrypt/live/api.example.com/fullchain.pem;
    ssl_certificate_key /etc/letsencrypt/live/api.example.com/privkey.pem;

    # BẮT BUỘC: Chỉ kích hoạt TLS 1.2 và TLS 1.3 (Vô hiệu hóa TLS 1.0, 1.1 và SSLv3)
    ssl_protocols TLSv1.2 TLSv1.3;

    # Ưu tiên các Cipher Suites mạnh mẽ hỗ trợ Perfect Forward Secrecy (ECDHE)
    ssl_ciphers 'ECDHE-ECDSA-AES128-GCM-SHA256:ECDHE-RSA-AES128-GCM-SHA256:ECDHE-ECDSA-AES256-GCM-SHA384:ECDHE-RSA-AES256-GCM-SHA384';
    ssl_prefer_server_ciphers on;

    # Tối ưu hóa hiệu năng: Cache phiên TLS để tránh handshake lại cho các kết nối liên tục
    ssl_session_cache shared:SSL:20m;
    ssl_session_timeout 1d;
    ssl_session_tickets off; # Tắt ticket nếu không quản lý key rotation chặt chẽ

    # HSTS: Buộc trình duyệt luôn gọi HTTPS trong vòng 1 năm
    add_header Strict-Transport-Security "max-age=31536000; includeSubDomains; preload" always;

    location / {
        proxy_pass http://127.0.0.1:3000;
        proxy_set_header X-Forwarded-Proto https;
    }
}

