// Cấu hình CORS chuẩn sản xuất với Whitelist động và Preflight Caching trên Express
import express from 'express';
import cors, { CorsOptions } from 'cors';

const app = express();

const ALLOWED_ORIGINS = [
  'https://mybrand.com',
  'https://admin.mybrand.com',
  'https://staging.mybrand.com'
];

const corsOptions: CorsOptions = {
  origin: (origin, callback) => {
    // Cho phép requests không có origin (như Mobile App, Server-to-Server, Curl)
    if (!origin) return callback(null, true);

    if (ALLOWED_ORIGINS.includes(origin)) {
      return callback(null, true);
    } else {
      return callback(new Error('Chính sách CORS không cho phép truy cập từ Origin này!'));
    }
  },
  methods: ['GET', 'POST', 'PUT', 'PATCH', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization', 'X-Requested-With'],
  credentials: true, // Cho phép truyền Cookie / Authorization Header
  maxAge: 86400      // 24 giờ: Trình duyệt cache lại preflight OPTIONS, tránh gửi OPTIONS liên tục
};

// Kích hoạt CORS middleware
app.use(cors(corsOptions));
// Tự động xử lý Preflight cho toàn bộ routes
app.options('*', cors(corsOptions));

