// Quản lý Secrets an toàn trong Node.js: Tích hợp AWS Secrets Manager thay vì đọc file .env
import { SecretsManagerClient, GetSecretValueCommand } from '@aws-sdk/client-secrets-manager';

class SecretsService {
  private client: SecretsManagerClient;
  private cachedSecrets: Record<string, string> = {};

  constructor() {
    // Xác thực bằng IAM Role của EC2/EKS (Không cần hardcode AccessKey/SecretKey)
    this.client = new SecretsManagerClient({ region: process.env.AWS_REGION || 'ap-southeast-1' });
  }

  async getSecret(secretName: string): Promise<string> {
    if (this.cachedSecrets[secretName]) {
      return this.cachedSecrets[secretName];
    }

    try {
      const command = new GetSecretValueCommand({ SecretId: secretName });
      const response = await this.client.send(command);

      if (response.SecretString) {
        this.cachedSecrets[secretName] = response.SecretString;
        return response.SecretString;
      }
      throw new Error('Secret không chứa dữ liệu dạng chuỗi');
    } catch (error) {
      console.error(`Lỗi khi lấy secret ${secretName} từ AWS:`, error);
      throw error;
    }
  }
}

export const secretsService = new SecretsService();

