// Thiết kế ABAC Policy Engine linh hoạt bằng TypeScript

interface UserSubject {
  id: string;
  department: string;
  roles: string[];
}

interface DocumentResource {
  id: string;
  ownerId: string;
  department: string;
  isClassified: boolean;
}

interface AccessContext {
  currentTime: Date;
  ipAddress: string;
}

// Hàm kiểm tra quyền theo mô hình ABAC linh hoạt
export function canAccessDocument(
  user: UserSubject,
  action: 'READ' | 'EDIT' | 'DELETE',
  doc: DocumentResource,
  context: AccessContext
): boolean {
  // 1. Quản trị viên tối cao luôn có quyền
  if (user.roles.includes('SUPER_ADMIN')) return true;

  // 2. Kiểm tra quyền ĐỌC (READ) dựa trên thuộc tính
  if (action === 'READ') {
    // Tài liệu tuyệt mật chỉ được đọc trong giờ làm việc (8h - 18h)
    const hour = context.currentTime.getHours();
    if (doc.isClassified && (hour < 8 || hour >= 18)) {
      return false;
    }
    // Nhân viên chỉ đọc được tài liệu thuộc phòng ban của mình HOẶC tài liệu do chính mình tạo
    return doc.department === user.department || doc.ownerId === user.id;
  }

  // 3. Quyền XÓA (DELETE): Chỉ chính chủ nhân tài liệu mới được xóa
  if (action === 'DELETE') {
    return doc.ownerId === user.id;
  }

  return false;
}

