// Minh họa: Validation bằng Zod và Sanitization bằng sanitize-html (TypeScript)
import { z } from 'zod';
import sanitizeHtml from 'sanitize-html';

// 1. INPUT VALIDATION: Kiểm tra cấu trúc chặt chẽ (Fail-fast)
export const CreatePostSchema = z.object({
  title: z.string().trim().min(5, 'Tiêu đề tối thiểu 5 ký tự').max(150, 'Tiêu đề tối đa 150 ký tự'),
  content: z.string().min(20, 'Nội dung tối thiểu 20 ký tự').max(50000),
  tags: z.array(z.string().regex(/^[a-z0-9-]+$/, 'Tag chỉ gồm chữ thường và dấu gạch')).max(5),
  authorEmail: z.string().email('Email không đúng định dạng')
});

export type CreatePostInput = z.infer<typeof CreatePostSchema>;

// 2. INPUT SANITIZATION: Làm sạch nội dung giàu định dạng (Rich Text HTML)
export function sanitizeArticleContent(rawHtml: string): string {
  return sanitizeHtml(rawHtml, {
    // Chỉ cho phép các thẻ HTML văn bản an toàn
    allowedTags: ['b', 'i', 'em', 'strong', 'a', 'p', 'ul', 'ol', 'li', 'code', 'pre'],
    allowedAttributes: {
      'a': ['href', 'target', 'rel']
    },
    // Bắt buộc link ngoài phải có rel="noopener noreferrer nofollow" chống tabnabbing
    transformTags: {
      'a': sanitizeHtml.simpleTransform('a', { rel: 'noopener noreferrer nofollow', target: '_blank' })
    }
  });
}

