// Xử lý upload ảnh bảo mật toàn diện bằng Node.js, file-type và Sharp
import { Request, Response } from 'express';
import { fromBuffer } from 'file-type';
import sharp from 'sharp';
import crypto from 'node:crypto';
import { s3Client } from './s3';

const ALLOWED_MIME_TYPES = ['image/jpeg', 'image/png', 'image/webp'];
const MAX_FILE_SIZE = 5 * 1024 * 1024; // 5MB

export async function secureImageUpload(req: Request, res: Response) {
  const fileBuffer = req.file?.buffer;

  if (!fileBuffer || fileBuffer.length > MAX_FILE_SIZE) {
    return res.status(400).json({ error: 'File không hợp lệ hoặc vượt quá 5MB' });
  }

  // 1. KIỂM TRA MAGIC BYTES (Chữ ký nhị phân thực tế của tệp)
  const fileType = await fromBuffer(fileBuffer);
  if (!fileType || !ALLOWED_MIME_TYPES.includes(fileType.mime)) {
    return res.status(400).json({ error: 'Chỉ chấp nhận file ảnh JPEG, PNG hoặc WebP hợp lệ' });
  }

  // 2. TÁI MÃ HÓA ẢNH (Re-encoding): Xóa sạch EXIF metadata và loại bỏ PHP webshell ẩn
  const sanitizedBuffer = await sharp(fileBuffer)
    .resize(1000, 1000, { fit: 'inside', withoutEnlargement: true })
    .toFormat('webp', { quality: 80 })
    .toBuffer();

  // 3. ĐỔI TÊN NGẪU NHIÊN BẰNG UUID (Tuyệt đối không dùng tên file của người dùng)
  const safeFilename = `avatars/${crypto.randomUUID()}.webp`;

  // 4. LƯU LÊN OBJECT STORAGE ĐỘC LẬP (AWS S3)
  await s3Client.putObject({
    Bucket: process.env.S3_UPLOAD_BUCKET!,
    Key: safeFilename,
    Body: sanitizedBuffer,
    ContentType: 'image/webp',
    Metadata: { 'original-name-hash': crypto.createHash('md5').update(req.file!.originalname).digest('hex') }
  });

  return res.status(201).json({
    url: `https://cdn.example.com/${safeFilename}`
  });
}

