// Luồng Authorization Code Flow kết hợp PKCE chuẩn OAuth 2.1 (TypeScript/Node.js)
import crypto from 'node:crypto';

// 1. Phía Client (SPA / Mobile): Tạo PKCE Code Verifier & Challenge
export function generatePKCE() {
  // Code Verifier: Chuỗi ngẫu nhiên có độ dài 43-128 ký tự
  const codeVerifier = crypto.randomBytes(32).toString('base64url');

  // Code Challenge: SHA-256 hash của Verifier
  const codeChallenge = crypto
    .createHash('sha256')
    .update(codeVerifier)
    .digest('base64url');

  return { codeVerifier, codeChallenge };
}

// 2. Xây dựng URL chuyển hướng người dùng đến Auth Server
export function buildAuthorizationUrl(codeChallenge: string, state: string): string {
  const params = new URLSearchParams({
    response_type: 'code',
    client_id: 'spa-web-client-id',
    redirect_uri: 'https://app.example.com/callback',
    scope: 'openid profile email offline_access',
    state: state, // Chống tấn công CSRF
    code_challenge: codeChallenge,
    code_challenge_method: 'S256'
  });

  return `https://auth.example.com/oauth/authorize?${params.toString()}`;
}

// 3. Phía Client gửi code + code_verifier để đổi token
export async function exchangeCodeForTokens(code: string, codeVerifier: string) {
  const response = await fetch('https://auth.example.com/oauth/token', {
    method: 'POST',
    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    body: new URLSearchParams({
      grant_type: 'authorization_code',
      client_id: 'spa-web-client-id',
      code: code,
      redirect_uri: 'https://app.example.com/callback',
      code_verifier: codeVerifier // Auth server băm lại bằng SHA-256 để verify với code_challenge ban đầu
    })
  });

  return await response.json();
}

