// Giải pháp kết hợp: Redis Denylist theo 'jti' và Token Versioning (TypeScript)
import { Request, Response, NextFunction } from 'express';
import jwt from 'jsonwebtoken';
import Redis from 'ioredis';

const redis = new Redis();

interface AppJwtPayload extends jwt.JwtPayload {
  sub: string;
  jti: string;
  tokenVersion: number;
}

// 1. Khi người dùng Logout đơn lẻ: Đưa token vào Redis Denylist
export async function logoutUser(token: string) {
  const decoded = jwt.decode(token) as AppJwtPayload;
  if (!decoded || !decoded.exp || !decoded.jti) return;

  const remainingTtlSeconds = decoded.exp - Math.floor(Date.now() / 1000);
  if (remainingTtlSeconds > 0) {
    // Lưu vào Redis với TTL tự động giải phóng bộ nhớ khi token hết hạn tự nhiên
    await redis.set(`blacklist:${decoded.jti}`, 'revoked', 'EX', remainingTtlSeconds);
  }
}

// 2. Khi người dùng bấm "Đăng xuất khỏi TẤT CẢ thiết bị": Tăng token_version
export async function logoutAllDevices(userId: string) {
  await db.user.update({
    where: { id: userId },
    data: { tokenVersion: { increment: 1 } }
  });
}

// 3. Middleware xác thực: Kiểm tra cả Denylist và Token Version
export async function authMiddleware(req: Request, res: Response, next: NextFunction) {
  const token = req.headers.authorization?.replace('Bearer ', '');
  if (!token) return res.status(401).json({ error: 'Token missing' });

  try {
    const payload = jwt.verify(token, process.env.JWT_SECRET!) as AppJwtPayload;

    // Kiểm tra nhanh Redis Denylist (O(1) memory lookup)
    const isRevoked = await redis.exists(`blacklist:${payload.jti}`);
    if (isRevoked) {
      return res.status(401).json({ error: 'Token đã bị thu hồi (Logged out)' });
    }

    req.user = payload;
    return next();
  } catch (err) {
    return res.status(401).json({ error: 'Token không hợp lệ hoặc đã hết hạn' });
  }
}

