// So sánh Server TCP và Server UDP cơ bản bằng Node.js core modules
import net from 'node:net';
import dgram from 'node:dgram';

// 1. TCP SERVER: Đảm bảo toàn vẹn, hướng kết nối (Reliable Stream)
const tcpServer = net.createServer((socket) => {
  console.log('Client TCP đã kết nối qua 3-way handshake');

  socket.on('data', (data) => {
    // Dữ liệu chắc chắn đến đúng thứ tự và không bị mất gói
    socket.write(`TCP ACK: Đã nhận ${data.length} bytes`);
  });
});
tcpServer.listen(8080, () => console.log('TCP Server lắng nghe cổng 8080'));

// 2. UDP SERVER: Không bắt tay, tốc độ cao (Fast Datagram)
const udpServer = dgram.createSocket('udp4');

udpServer.on('message', (msg, rinfo) => {
  // Nhận trực tiếp từng gói tin độc lập, có thể mất gói hoặc đảo lộn thứ tự qua mạng
  console.log(`UDP nhận từ ${rinfo.address}:${rinfo.port}: ${msg.toString()}`);

  const response = Buffer.from('UDP Pong');
  udpServer.send(response, rinfo.port, rinfo.address);
});
udpServer.bind(9090, () => console.log('UDP Server lắng nghe cổng 9090'));

