// Truy vấn phân giải DNS trực tiếp bằng Node.js DNS Module
import dns from 'node:dns/promises';

async function resolveDomainInfrastructure(domain: string) {
  try {
    console.log(`=== BẮT ĐẦU PHÂN GIẢI TÊN MIỀN: ${domain} ===`);

    // 1. Phân giải địa chỉ IPv4 (Bản ghi A)
    const ipv4Addresses = await dns.resolve4(domain);
    console.log('IPv4 Addresses (A Record):', ipv4Addresses);

    // 2. Phân giải địa chỉ IPv6 (Bản ghi AAAA)
    try {
      const ipv6Addresses = await dns.resolve6(domain);
      console.log('IPv6 Addresses (AAAA Record):', ipv6Addresses);
    } catch {
      console.log('Domain không cấu hình IPv6.');
    }

    // 3. Tìm máy chủ DNS có thẩm quyền (Authoritative Nameservers - NS Record)
    const nameServers = await dns.resolveNs(domain);
    console.log('Authoritative Name Servers (NS Record):', nameServers);

    // 4. Kiểm tra cấu hình Mail Server (MX Record)
    const mxRecords = await dns.resolveMx(domain);
    console.log('Mail Exchange Servers (MX Record):', mxRecords);

  } catch (error) {
    console.error('Lỗi phân giải DNS:', error);
  }
}

// Chạy thử nghiệm
resolveDomainInfrastructure('google.com');

